question": "What is the largest winning scoreline in official Clásico history?", "difficulty": "boss", "options": [{"label": "Real Madrid 11–1 Barcelona", "isCorrect": true}, {"label": "Barcelona 8–0 Real Madrid", "isCorrect": false}, {"label": "Real Madrid 9–0 Barcelona", "isCorrect": false}, {"label": "Barcelona 7–0 Real Madrid", "isCorrect": false}]}, {"question": "In which year did Real Madrid defeat Barcelona 11–1?", "difficulty": "boss", "options": [{"label": "1943", "isCorrect": true}, {"label": "1935", "isCorrect": false}, {"label": "1950", "isCorrect": false}, {"label": "1960", "isCorrect": false}]}, {"question": "Which competition featured the 1943 11–1 match?", "difficulty": "boss", "options": [{"label": "Copa del Generalísimo", "isCorrect": true}, {"label": "La Liga", "isCorrect": false}, {"label": "European Cup", "isCorrect": false}, {"label": "Spanish Super Cup", "isCorrect": false}]}, {"question": "What is the biggest victory margin in a La Liga Clásico?", "difficulty": "boss", "options": [{"label": "Six goals", "isCorrect": true}, {"label": "Eight goals", "isCorrect": false}, {"label": "Ten goals", "isCorrect": false}, {"label": "Four goals", "isCorrect": false}]}, {"question": "What was the score when Real Madrid achieved that league record in 1935?", "difficulty": "boss", "options": [{"label": "8–2", "isCorrect": true}, {"label": "6–0", "isCorrect": false}, {"label": "7–1", "isCorrect": false}, {"label": "9–3", "isCorrect": false}]}, {"question": "Which Barcelona player scored a hat-trick in the 5–0 league victory in January 1994?", "difficulty": "boss", "options": [{"label": "Romário", "isCorrect": true}, {"label": "Hristo Stoichkov", "isCorrect": false}, {"label": "Rivaldo", "isCorrect": false}, {"label": "Ronaldinho", "isCorrect": false}]}, {"question": "Which Real Madrid striker scored a hat-trick in the 5–0 league victory in January 1995?", "difficulty": "boss", "options": [{"label": "Iván Zamorano", "isCorrect": true}, {"label": "Raúl", "isCorrect": false}, {"label": "Fernando Morientes", "isCorrect": false}, {"label": "Ronaldo Nazário", "isCorrect": false}]}, {"question": "Which Barcelona player received a standing ovation from Madrid fans at the Bernabéu in 2005?", "difficulty": "boss", "options": [{"label": "Ronaldinho", "isCorrect": true}, {"label": "Lionel Messi", "isCorrect": false}, {"label": "Xavi", "isCorrect": false}, {"label": "Samuel Eto'o", "isCorrect": false}]}, {"question": "Who scored twice for Barcelona in that November 2005 league Clásico?", "difficulty": "boss", "options": [{"label": "Ronaldinho", "isCorrect": true}, {"label": "Samuel Eto'o", "isCorrect": false}, {"label": "Deco", "isCorrect": false}, {"label": "Ludovic Giuly", "isCorrect": false}]}, {"question": "What was the final score of that November 2005 match?", "difficulty": "boss", "options": [{"label": "Real Madrid 0–3 Barcelona", "isCorrect": true}, {"label": "Real Madrid 1–2 Barcelona", "isCorrect": false}, {"label": "Real Madrid 2–2 Barcelona", "isCorrect": false}, {"label": "Real Madrid 0–4 Barcelona", "isCorrect": false}]}, {"question": "Which Real Madrid legend won six European Cups as a player?", "difficulty": "boss", "options": [{"label": "Paco Gento", "isCorrect": true}, {"label": "Alfredo Di Stéfano", "isCorrect": false}, {"label": "Raúl", "isCorrect": false}, {"label": "Iker Casillas", "isCorrect": false}]}, {"question": "Which former Barcelona player coached the club's famous Dream Team?", "difficulty": "boss", "options": [{"label": "Johan Cruyff", "isCorrect": true}, {"label": "Pep Guardiola", "isCorrect": false}, {"label": "Luis Enrique", "isCorrect": false}, {"label": "Frank Rijkaard", "isCorrect": false}]}, {"question": "Which team eliminated Barcelona in the 2001–02 Champions League semi-finals?", "difficulty": "boss", "options": [{"label": "Real Madrid", "isCorrect": true}, {"label": "Bayern Munich", "isCorrect": false}, {"label": "Manchester United", "isCorrect": false}, {"label": "Juventus", "isCorrect": false}]}]$bank$::jsonb)
      as entry(question text, difficulty text, options jsonb)
  loop
    select id into question_id from public.quiz_questions where question = item.question limit 1;
    if question_id is null then
      insert into public.quiz_questions(question, category, difficulty, explanation, status)
      values (item.question, 'El Clásico', item.difficulty, null, 'active')
      returning id into question_id;
    end if;
    if not exists (select 1 from public.quiz_options where quiz_options.question_id = question_id) then
      for option_item in
        select value, ordinality
        from jsonb_array_elements(item.options) with ordinality as options(value, ordinality)
      loop
        insert into public.quiz_options(question_id, label, is_correct, sort_order)
        values (question_id, option_item.value->>'label', (option_item.value->>'isCorrect')::boolean, option_item.ordinality::integer);
      end loop;
    end if;
    question_id := null;
  end loop;
end
$seed$;
